def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [[0 for _ in range(cols)] for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            result[r][c] = grid[r][c]  # Copy input

    for r in range(rows - 2):
        for c in range(cols - 2):
            # Get the 3x3 block
            block = []
            for dr in range(3):
                for dc in range(3):
                    block.append(grid[r+dr][c+dc])

            # Count each color in this 3x3
            from collections import Counter
            counts = Counter(block)

            # If exactly 2 colors, one appears 8 times (perimeter), one appears 1 time (center)
            if len(counts) == 2 and 8 in counts.values():
                # The color with 8 occurrences is the perimeter, 1 is the center
                for dr in range(3):
                    for dc in range(3):
                        result[r+dr][c+dc] = 3  # Convert to 3s
    return result
